/**
 * @param  array<string, array<string, list<ScannedFile>>>  $scans  package slug => (module => files)
 */
function render(array $scans): string
{
    $lines = [BANNER];

    foreach (\ArazzoDocs\PACKAGE_LAYER_ORDER as $package) {
        $contract = PACKAGE_CONTRACTS[$package] ?? null;
        if ($contract === null) {
            continue;
        }
        $modules = $scans[$package] ?? [];

        $lines[] = '## '.$package;
        $lines[] = '';
        $lines[] = '> **Provides:** '.$contract['provides'];
        $lines[] = '';
        $lines[] = '### Capabilities';
        $lines[] = '';
        foreach ($contract['capabilities'] as $capability) {
            $lines[] = '- '.$capability;
        }
        $lines[] = '';
        $lines[] = '### Public entry surface';
        $lines[] = '';
        foreach ($contract['faces'] as $face) {
            $lines = [...$lines, ...renderFace($modules, $face)];
        }
        $lines[] = '';
        $lines[] = '### Cross-boundary value types';
        $lines[] = '';
        if ($contract['value_types'] === []) {
            $lines[] = '_None — the entry surface exchanges plain arrays._';
        } else {
            foreach ($contract['value_types'] as $valueType) {
                $file = findInPackage($modules, $valueType);
                $status = $file === null ? ' not found' : ' present';
                $lines[] = '- `'.$valueType.'` —'.$status;
            }
        }
        $lines[] = '';
        $lines[] = '### Deliberately internal';
        $lines[] = '';
        foreach ($contract['internal'] as $internal) {
            $lines[] = renderInternal($modules, $internal);
        }
        $lines[] = '';
    }

    return implode("\n", $lines)."\n";
}

/**
 * @param  array<string, list<ScannedFile>>  $modules
 * @return list<string>
 */
function renderFace(array $modules, string $face): array
{
    $file = findInPackage($modules, $face);
    if ($file === null) {
        return ['- `'.$face.'` — _not found in scan_'];
    }
    $kind = $file->isInterface ? 'interface' : 'class';
    $internalMark = \ArazzoDocs\hasInternalDocblock($file->content) ? ' ⚠ marked `@internal` — contradicts its face role' : '';
    $lines = ['- `'.$face.'` (`'.$kind.'`)'.$internalMark];
    foreach (\ArazzoDocs\PublicApiDoc\publicSignatures($file->content) as $signature) {
        $lines[] = '  - `'.$signature.'`';
    }

    return $lines;
}

/**
 * @param  array<string, list<ScannedFile>>  $modules
 */
function renderInternal(array $modules, string $internal): string
{
    if (str_ends_with($internal, '\\*')) {
        return '- `'.$internal.'` — whole namespace (declared target)';
    }
    $file = findInPackage($modules, $internal);
    if ($file === null) {
        return '- `'.$internal.'` — _not found in scan_';
    }
    $marked = \ArazzoDocs\hasInternalDocblock($file->content) ? 'yes' : 'no (target for the sweep)';

    return '- `'.$internal.'` — `@internal`: '.$marked;
}

/**
 * First scanned file whose class short-name matches inside a package.
 *
 * @param  array<string, list<ScannedFile>>  $modules
 */
function findInPackage(array $modules, string $short): ?ScannedFile
{
    foreach ($modules as $files) {
        foreach ($files as $file) {
            if ($file->className === $short) {
                return $file;
            }
        }
    }

    return null;
}
